-- Economics G2 T7 content upgrade: append-only question versions; transaction aborts on any violation.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
DO $t$
DECLARE
 d jsonb:='[{"ref":"EC9708:G2:EC9708-G2-T7-P-006","d":"hard","sec":185,"k":"C","en":"A trade-weighted currency index uses partner weights 50%, 30%, and 20%. Partner B''s exchange-rate index is 90 and C''s is 110. What must partner A''s index be for the overall index to equal 105? If A''s index then rises by five points with other indices unchanged, what is the new overall index?","ru":"Торгово-взвешенный валютный индекс использует веса партнёров A, B и C: 50%, 30% и 20%. Индекс курса B равен 90, C — 110. Каким должен быть индекс A, чтобы общий индекс составил 105? Если затем индекс A повысится на пять пунктов при неизменных остальных, чему станет равен общий индекс?","uz":"Savdo vaznli valuta indeksida A, B, C hamkorlar vazni 50%, 30%, 20%. B kurs indeksi 90, C indeksi 110. Umumiy indeks 105 bo‘lishi uchun A indeksi nechaga teng bo‘lishi kerak? Keyin A indeksi besh punkt oshib, boshqalari o‘zgarmasa yangi umumiy indeks qancha?","options_en":["A=110; new index 107.5","A=112; new index 110","A=112; new index 107.5","A=116; new index 105"],"options_ru":["A=110; новый индекс 107,5","A=112; новый индекс 110","A=112; новый индекс 107,5","A=116; новый индекс 105"],"options_uz":["A=110; yangi indeks 107,5","A=112; yangi indeks 110","A=112; yangi indeks 107,5","A=116; yangi indeks 105"],"why":["105=0.5A+0.3×90+0.2×110 gives 0.5A=56, so A=112. Adding five points to A adds 0.5×5=2.5 points to the aggregate, giving 107.5.","Из 105=0,5A+0,3×90+0,2×110 следует A=112. Рост A на пять пунктов увеличивает общий индекс на 0,5×5=2,5, до 107,5.","105=0,5A+0,3×90+0,2×110 dan A=112. A besh punkt oshsa jami indeks 0,5×5=2,5 punkt oshib 107,5 bo‘ladi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-008","d":"hard","sec":195,"k":"D","en":"A country starts with a current-account deficit of $60m. A cut in domestic expenditure reduces imports by $7m. An import-switching tariff separately reduces imports by $9m, but imported-input costs cause exports to decline by $4m. Assuming these changes do not overlap and other flows stay constant, what is the new current-account balance?","ru":"Страна имеет дефицит текущего счёта $60 млн. Сокращение внутренних расходов уменьшает импорт на $7 млн. Пошлина, переключающая спрос на отечественные товары, отдельно снижает импорт на $9 млн, но рост затрат на импортные ресурсы сокращает экспорт на $4 млн. Эффекты не пересекаются, прочие потоки неизменны. Каково новое сальдо текущего счёта?","uz":"Mamlakat joriy hisobida $60 mln taqchillik bor. Ichki xarajatlarni qisqartirish importni $7 mln kamaytiradi. Import o‘rnini bosuvchi boj alohida importni $9 mln qisqartiradi, ammo import xomashyo xarajati eksportni $4 mln kamaytiradi. Ta’sirlar takrorlanmaydi, boshqa oqimlar o‘zgarmaydi. Yangi joriy hisob balansi qancha?","options_en":["−$40m","−$52m","−$56m","−$48m"],"options_ru":["−$40 млн","−$52 млн","−$56 млн","−$48 млн"],"options_uz":["−$40 mln","−$52 mln","−$56 mln","−$48 mln"],"why":["The balance improves by $7m+$9m−$4m=$12m. Starting at −$60m, the new balance is −$48m. Input-cost effects can partly offset a tariff''s import-reduction benefit.","Сальдо улучшается на $7+$9−$4=$12 млн, с −$60 до −$48 млн. Рост импортных издержек для экспортёров частично нивелирует эффект пошлины.","Balans $7+$9−$4=$12 mln yaxshilanadi; −$60 mln dan −$48 mln ga o‘tadi. Eksport xarajatlari bojning foydasini qisman kamaytiradi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-012","d":"hard","sec":180,"k":"B","en":"In a country, nominal GDP rises by 12% over one year, the GDP deflator rises by 8%, and population rises by 4%. Using exact index ratios, approximately how does real GDP per person change?","ru":"За год номинальный ВВП страны вырос на 12%, дефлятор ВВП — на 8%, а население — на 4%. Используя точные отношения индексов, как примерно изменился реальный ВВП на человека?","uz":"Bir yilda mamlakat nominal YaIMi 12%, YaIM deflyatori 8%, aholisi esa 4% oshdi. Indekslarning aniq nisbatiga asoslanib, jon boshiga real YaIM taxminan qanday o‘zgardi?","options_en":["Rises about 0.3%","Falls about 0.3%","Rises exactly 4%","Falls exactly 4%"],"options_ru":["Растёт примерно на 0,3%","Снижается примерно на 0,3%","Растёт ровно на 4%","Снижается ровно на 4%"],"options_uz":["Taxminan 0,3% oshadi","Taxminan 0,3% tushadi","Aynan 4% oshadi","Aynan 4% kamayadi"],"why":["The real GDP-per-person factor is 1.12/(1.08×1.04)=1.12/1.1232≈0.99715, or a fall of about 0.285%. Nominal growth alone is misleading.","Индекс реального ВВП на человека равен 1,12/(1,08×1,04)≈0,99715; снижение около 0,285%. Номинальный рост не означает рост на человека.","Jon boshiga real YaIM koeffitsienti 1,12/(1,08×1,04)≈0,99715, ya’ni taxminan 0,285% kamayish. Nominal o‘sishning o‘zi yetarli emas."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-014","d":"hard","sec":175,"k":"A","en":"Under a fixed exchange-rate regime, the government officially changes the peg from 8 domestic currency units per US dollar to 6.4 domestic units per dollar. An export sells for 160 domestic units with its domestic price unchanged. What happens to its dollar price, and how is the official currency move described?","ru":"При фиксированном курсе власти официально меняют привязку с 8 до 6,4 единицы национальной валюты за доллар. Экспортный товар стоит 160 национальных единиц, внутренняя цена неизменна. Как меняется цена товара в долларах и как называется официальное изменение курса?","uz":"Qat’iy kursda hukumat bir dollar uchun kursni 8 mahalliy birlikdan 6,4 birlikka rasmiy o‘zgartiradi. Eksport mahsuloti 160 mahalliy birlik turadi, ichki narxi o‘zgarmaydi. Uning dollar narxi qanday o‘zgaradi va rasmiy kurs harakati nima deyiladi?","options_en":["$20 to $25; revaluation","$20 to $16; devaluation","$25 to $20; devaluation","$20 to $25; depreciation under a floating rate"],"options_ru":["С $20 до $25; ревальвация","С $20 до $16; девальвация","С $25 до $20; девальвация","С $20 до $25; обесценение при плавающем курсе"],"options_uz":["$20 dan $25 ga; revalvatsiya","$20 dan $16 ga; devalvatsiya","$25 dan $20 ga; devalvatsiya","$20 dan $25 ga; suzuvchi kursda qadrsizlanish"],"why":["Dollar price rises from 160/8=$20 to 160/6.4=$25. Fewer domestic units per dollar represent an official strengthening (revaluation) under a fixed peg.","Цена в долларах растёт с 160/8=$20 до 160/6,4=$25. Укрепление национальной валюты по решению властей при фиксированном курсе — ревальвация.","Dollar narxi 160/8=$20 dan 160/6,4=$25 ga oshadi. Qat’iy kursni rasmiy kuchaytirish revalvatsiya deyiladi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-017","d":"hard","sec":190,"k":"C","en":"To resist depreciation, a central bank sells $80m of foreign reserves and buys domestic currency, withdrawing the equivalent amount of domestic base money. It then buys $60m of government bonds using newly created domestic reserves. Assume dollar-equivalent values are comparable and no other flows occur. What is the net monetary-base effect, and by how much do foreign reserves change?","ru":"Для сдерживания обесценения центральный банк продаёт $80 млн валютных резервов и покупает национальную валюту, изымая эквивалентную сумму денежной базы. Затем покупает гособлигации на $60 млн за вновь созданные резервы. Долларовые эквиваленты сопоставимы, других операций нет. Каково чистое изменение денежной базы и валютных резервов?","uz":"Qadrsizlanishni to‘xtatish uchun markaziy bank $80 mln valuta zaxirasini sotib, mahalliy valutani sotib oladi va teng pul bazasini kamaytiradi. Keyin yangi mahalliy zaxira yaratib $60 mln davlat obligatsiyasini xarid qiladi. Dollar ekvivalentlari taqqoslanadi, boshqa oqim yo‘q. Pul bazasi va valuta zaxirasi qanday o‘zgaradi?","options_en":["Base +$140m; reserves +$80m","Base −$80m; reserves unchanged","Base −$20m; foreign reserves −$80m","Base +$20m; foreign reserves +$60m"],"options_ru":["База +$140 млн; резервы +$80 млн","База −$80 млн; резервы неизменны","База −$20 млн; валютные резервы −$80 млн","База +$20 млн; валютные резервы +$60 млн"],"options_uz":["Baza +$140 mln; zaxira +$80 mln","Baza −$80 mln; zaxira o‘zgarmaydi","Baza −$20 mln; valuta zaxirasi −$80 mln","Baza +$20 mln; valuta zaxirasi +$60 mln"],"why":["FX support withdraws $80m of base money and reduces reserves by $80m. Bond purchases re-inject $60m base money, leaving a net −$20m monetary-base change while foreign reserves stay $80m lower.","Поддержка курса изымает $80 млн базы и уменьшает валютные резервы на $80 млн. Покупка облигаций возвращает $60 млн в базу: чистое изменение −$20 млн.","Kursni qo‘llash bazani $80 mln va valuta zaxirasini $80 mln kamaytiradi. Obligatsiya xaridi bazaga $60 mln qaytaradi; sof baza −$20 mln."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-019","d":"hard","sec":195,"k":"B","en":"A country''s initial annual exports are $500m and imports $600m. Just after depreciation, existing import contracts raise the domestic-currency import bill to $690m while export receipts stay $500m. Later, after volumes adjust, export receipts reach $650m and the import bill falls to $580m. What are the short-run and later trade balances?","ru":"Изначально годовой экспорт страны $500 млн, импорт $600 млн. Сразу после обесценения действующие импортные контракты повышают счёт за импорт в местной валюте до $690 млн, экспортная выручка остаётся $500 млн. Позже, после изменения объёмов, экспортная выручка достигает $650 млн, импортный счёт снижается до $580 млн. Каковы краткосрочное и последующее торговые сальдо?","uz":"Mamlakatning dastlabki yillik eksporti $500 mln, importi $600 mln. Qadrsizlanishdan darhol keyin eski import shartnomalari mahalliy valutadagi import to‘lovini $690 mln qiladi, eksport tushumi $500 mln qoladi. Keyin hajmlar moslashib, eksport $650 mln, import $580 mln bo‘ladi. Qisqa va keyingi davr savdo balansi qanday?","options_en":["Short-run +$190m; later −$70m","Short-run −$190m; later +$70m","Short-run −$100m; later −$100m","Short-run −$90m; later +$70m"],"options_ru":["Сначала +$190 млн; затем −$70 млн","Сначала −$190 млн; затем +$70 млн","Сначала −$100 млн; затем −$100 млн","Сначала −$90 млн; затем +$70 млн"],"options_uz":["Dastlab +$190 mln; keyin −$70 mln","Dastlab −$190 mln; keyin +$70 mln","Dastlab −$100 mln; keyin −$100 mln","Dastlab −$90 mln; keyin +$70 mln"],"why":["Immediately exports−imports=500−690=−$190m, compared with −$100m before. Later balance=650−580=+$70m, illustrating the J-curve adjustment path.","Сразу после изменения сальдо 500−690=−$190 млн вместо прежних −$100 млн; затем 650−580=+$70 млн. Это соответствует J-образной динамике.","Darhol balans 500−690=−$190 mln, avval −$100 mln edi. Keyin 650−580=+$70 mln; bu J-egri chizig‘i mexanizmiga mos."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-020","d":"hard","sec":185,"k":"D","en":"A monetary authority starts with $900m of usable foreign reserves and average monthly imports of $150m. It sells $225m of reserves to defend a fixed exchange-rate peg, with monthly imports unchanged. What happens to its import-cover ratio, and what constraint does this highlight?","ru":"Монетарные власти имеют $900 млн доступных валютных резервов, среднемесячный импорт $150 млн. Для защиты фиксированного курса они продают $225 млн резервов; импорт не меняется. Как изменится покрытие импорта резервами и какое ограничение это показывает?","uz":"Monetar organ $900 mln ishlatiladigan valuta zaxirasiga ega, oylik o‘rtacha import $150 mln. Qat’iy kursni himoyalash uchun $225 mln zaxira sotadi, import o‘zgarmaydi. Importni qoplash muddati qanday o‘zgaradi va bu nimani ko‘rsatadi?","options_en":["From 6 months to 7.5 months; the peg is costless","From 6 months to 3 months; reserves are unlimited","From 6 months to 6 months; reserves are irrelevant","From 6 months to 4.5 months; repeated intervention faces a finite-reserve limit"],"options_ru":["С 6 до 7,5 месяца; защита курса бесплатна","С 6 до 3 месяцев; резервы неограниченны","С 6 до 6 месяцев; резервы не имеют значения","С 6 до 4,5 месяца; повторные интервенции ограничены запасом резервов"],"options_uz":["6 oydan 7,5 oyga; kursni ushlash bepul","6 oydan 3 oyga; zaxira cheksiz","6 oy bo‘lib qoladi; zaxira ahamiyatsiz","6 oydan 4,5 oyga; takror intervensiya zaxira bilan cheklangan"],"why":["Reserves decline from $900m to $675m. Import cover changes from 900/150=6 months to 675/150=4.5 months. Fixed pegs may consume finite reserves.","Резервы снижаются до $675 млн. Покрытие импорта уменьшается с 900/150=6 до 675/150=4,5 месяца. Поддержка фиксированного курса ограничена.","Zaxira $675 mln ga tushadi. Import qoplash 900/150=6 oydan 675/150=4,5 oyga kamayadi. Qat’iy kursni himoyalash chegaralangan."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-023","d":"hard","sec":175,"k":"C","en":"A foreign parent builds and controls a new $80m factory in a host country. The factory purchases $45m of imported machinery during construction, while no other transactions occur in the simplified example. Which pair of balance-of-payments entries is directly associated with these transactions in the host country''s accounts?","ru":"Иностранная материнская компания строит и контролирует новый завод стоимостью $80 млн в принимающей стране. При строительстве завод покупает импортное оборудование на $45 млн; других операций в упрощённом примере нет. Какие две записи платёжного баланса непосредственно связаны с этими операциями у принимающей страны?","uz":"Xorijiy bosh kompaniya qabul qiluvchi davlatda $80 mln yangi zavod qurib nazorat qiladi. Qurilishda zavod $45 mln import uskuna xarid qiladi; soddalashtirilgan misolda boshqa operatsiya yo‘q. Qabul qiluvchi mamlakat to‘lov balansida shu operatsiyalarning ikki asosiy yozuvi qaysi?","options_en":["Direct-investment outflow $80m; goods exports $45m","Portfolio-investment inflow $80m; services exports $45m","Direct-investment inflow $80m in the financial account; goods imports $45m in the current account","Official aid inflow $80m; secondary-income inflow $45m"],"options_ru":["Отток прямых инвестиций $80 млн; экспорт товаров $45 млн","Приток портфельных инвестиций $80 млн; экспорт услуг $45 млн","Приток ПИИ $80 млн в финансовом счёте; импорт товаров $45 млн в текущем счёте","Приток помощи $80 млн; вторичные доходы $45 млн"],"options_uz":["$80 mln to‘g‘ridan-to‘g‘ri investitsiya chiqimi; $45 mln tovar eksporti","$80 mln portfel investitsiya kirimi; $45 mln xizmat eksporti","Moliyaviy hisobda $80 mln PII kirimi; joriy hisobda $45 mln tovar importi","$80 mln yordam kirimi; $45 mln ikkilamchi daromad"],"why":["Control and lasting participation identify FDI, recorded as a financial-account inflow (under the stated host-country presentation). Imported machinery is a goods import in the current account, not itself an aid transfer.","Контроль нового предприятия означает приток ПИИ по финансовому счёту. Купленное за границей оборудование отражается как импорт товаров по текущему счёту, не как помощь.","Nazorat qilinadigan yangi zavod PII kirimi, moliyaviy hisobga tegishli. Import uskunalar joriy hisobning tovar importi, yordam emas."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-027","d":"hard","sec":175,"k":"A","en":"In a Lorenz-curve diagram, the total area below the line of perfect equality is 0.50. The area between that line and the Lorenz curve falls from 0.20 to 0.14 after a policy. What happens to the Gini coefficient, and what cannot be concluded from this information alone?","ru":"На диаграмме Лоренца площадь под линией абсолютного равенства равна 0,50. После реформы площадь между этой линией и кривой Лоренца снизилась с 0,20 до 0,14. Как изменился коэффициент Джини и чего нельзя заключить только по этим данным?","uz":"Lorens diagramida mutlaq tenglik chizig‘i ostidagi maydon 0,50. Islohotdan keyin shu chiziq bilan Lorens egri chizig‘i orasidagi maydon 0,20 dan 0,14 ga tushdi. Jini koeffitsienti qanday o‘zgardi va faqat shu ma’lumotdan nimani aniqlab bo‘lmaydi?","options_en":["From 0.40 to 0.28; absolute poverty change is not established","From 0.20 to 0.14; poverty necessarily disappears","From 0.40 to 0.56; inequality worsens","From 0.50 to 0.14; average income must double"],"options_ru":["С 0,40 до 0,28; изменение абсолютной бедности не установлено","С 0,20 до 0,14; бедность обязательно исчезает","С 0,40 до 0,56; неравенство увеличивается","С 0,50 до 0,14; средний доход обязан удвоиться"],"options_uz":["0,40 dan 0,28 ga; mutlaq kambag‘allik o‘zgarishi noma’lum","0,20 dan 0,14 ga; kambag‘allik albatta yo‘qoladi","0,40 dan 0,56 ga; tengsizlik kuchayadi","0,50 dan 0,14 ga; o‘rtacha daromad ikki baravar oshadi"],"why":["Gini = area between equality line and Lorenz curve /0.50. It falls from 0.20/0.50=0.40 to 0.14/0.50=0.28. Distributional equality alone does not reveal absolute poverty.","Коэффициент Джини равен отношению площади к 0,50: 0,20/0,50=0,40, затем 0,14/0,50=0,28. Более равное распределение само по себе не показывает уровень абсолютной бедности.","Jini indeksi maydon/0,50; avval 0,20/0,50=0,40, keyin 0,14/0,50=0,28. Tenglik oshishi mutlaq kambag‘allik darajasini o‘zi ko‘rsatmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-031","d":"hard","sec":195,"k":"B","en":"Define the real exchange rate q=E×Pforeign/Pdomestic, where E is domestic currency per foreign currency and a higher q means real depreciation. Over one year E rises 10%, foreign prices rise 5%, and domestic prices rise 15%. Approximately what happens to q using exact index ratios?","ru":"Определим реальный курс q=E×Pвнеш/Pвнутр, где E — количество национальных единиц за иностранную, а рост q означает реальное обесценение. За год E растёт на 10%, внешние цены на 5%, внутренние на 15%. Как примерно меняется q по точным отношениям индексов?","uz":"Real kurs q=E×Pxorij/Pichki deb belgilansin, E — bir xorijiy birlik uchun mahalliy birliklar, q oshishi real qadrsizlanish. Bir yilda E 10%, xorijiy narxlar 5%, ichki narxlar 15% oshdi. Aniq indekslar bo‘yicha q taxminan qancha o‘zgaradi?","options_en":["Falls about 10%; real appreciation","Rises about 0.43%; slight real depreciation","Rises 30%; strong real depreciation","Unchanged; nominal and domestic inflation always cancel"],"options_ru":["Падает примерно на 10%; реальное укрепление","Растёт примерно на 0,43%; небольшое реальное обесценение","Растёт на 30%; сильное реальное обесценение","Не меняется; номинальный курс и инфляция всегда взаимно компенсируются"],"options_uz":["Taxminan 10% kamayadi; real qadrlanish","Taxminan 0,43% oshadi; kichik real qadrsizlanish","30% oshadi; kuchli real qadrsizlanish","O‘zgarmaydi; nominal kurs va ichki inflyatsiya doim qoplanadi"],"why":["The real exchange-rate factor is 1.10×1.05/1.15≈1.00435, giving ≈0.43% real depreciation despite a 10% nominal depreciation.","Реальный курс меняется в 1,10×1,05/1,15≈1,00435 раза, то есть обесценивается лишь примерно на 0,43% при 10% номинального изменения.","Real kurs koeffitsienti 1,10×1,05/1,15≈1,00435. Nominal 10% qadrsizlanishga qaramay, real qadrsizlanish taxminan 0,43%."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-032","d":"hard","sec":195,"k":"D","en":"A foreign-owned factory in a host country employs 1,000 local workers earning $20,000 each annually. Its annual operating profit is $30m, of which 40% is repatriated abroad. Ignoring other income flows, what are local wage income and the direct annual primary-income outflow from profit repatriation?","ru":"Иностранный завод в принимающей стране нанимает 1 000 местных работников с годовой оплатой $20 000 каждому. Годовая операционная прибыль $30 млн, из неё 40% переводится за границу. Игнорируя другие доходы, найдите заработную плату местных работников и ежегодный отток первичных доходов из-за репатриации прибыли.","uz":"Qabul qiluvchi mamlakatdagi xorijiy zavod 1000 mahalliy ishchini yiliga $20 000 dan yollaydi. Yillik operatsion foyda $30 mln, uning 40% i chetga chiqariladi. Boshqa daromad oqimlarini hisoblamasdan mahalliy ish haqi va foydani olib chiqishdagi yillik birlamchi daromad chiqimini toping.","options_en":["Wages $2m; primary-income outflow $30m","Wages $20m; primary-income outflow $18m","Wages $30m; primary-income outflow $12m","Wages $20m; primary-income outflow $12m"],"options_ru":["Зарплаты $2 млн; отток первичных доходов $30 млн","Зарплаты $20 млн; отток $18 млн","Зарплаты $30 млн; отток $12 млн","Зарплаты $20 млн; отток $12 млн"],"options_uz":["Ish haqi $2 mln; birlamchi daromad chiqimi $30 mln","Ish haqi $20 mln; chiqim $18 mln","Ish haqi $30 mln; chiqim $12 mln","Ish haqi $20 mln; chiqim $12 mln"],"why":["Local wage earnings are 1,000×$20,000=$20m. Profit repatriation is 40%×$30m=$12m, a primary-income outflow in the host economy''s current account.","Местные зарплаты 1 000×$20 000=$20 млн. Репатриация прибыли 40%×$30 млн=$12 млн отражается как отток первичных доходов.","Mahalliy ish haqi 1000×$20 000=$20 mln. Foyda olib chiqilishi 40%×$30 mln=$12 mln, joriy hisobda birlamchi daromad chiqimi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-033","d":"hard","sec":180,"k":"C","en":"A country defending a fixed currency peg starts with $750m of usable FX reserves and average monthly imports of $150m. Its central bank sells $150m of FX reserves, without replenishment. What happens to reserve import cover, and which comparison with floating exchange rates is accurate?","ru":"Страна защищает фиксированную валютную привязку, имея $750 млн доступных резервов при среднемесячном импорте $150 млн. Центральный банк продаёт $150 млн валютных резервов без восполнения. Как меняется покрытие импорта и какое сравнение с плавающим курсом верно?","uz":"Mamlakat qat’iy valuta kursini himoya qiladi: zaxiralar $750 mln, oylik import $150 mln. Markaziy bank $150 mln valuta zaxirasini sotadi va to‘ldirmaydi. Import qoplash muddati qanday o‘zgaradi va suzuvchi kurs bilan qaysi taqqoslash to‘g‘ri?","options_en":["From 5 to 6 months; floating rates never move","From 5 to 1 month; a peg uses no reserves","From 5 to 4 months; a floating rate can absorb market pressure through price movement without defending a fixed parity","From 5 to 4 months; both regimes guarantee the identical exchange rate"],"options_ru":["С 5 до 6 месяцев; плавающий курс никогда не меняется","С 5 до 1 месяца; фиксированный курс не расходует резервы","С 5 до 4 месяцев; при плавающем курсе давление может отражаться в изменении цены валюты без защиты заданного паритета","С 5 до 4 месяцев; оба режима гарантируют одинаковый курс"],"options_uz":["5 oydan 6 oyga; suzuvchi kurs hech o‘zgarmaydi","5 oydan 1 oyga; qat’iy kurs zaxira sarflamaydi","5 oydan 4 oyga; suzuvchi kursda bosim kurs o‘zgarishi orqali yutilishi mumkin, qat’iy paritet himoyasi shart emas","5 oydan 4 oyga; ikkala tizim ayni kursni kafolatlaydi"],"why":["Reserve cover falls from 750/150=5 to 600/150=4 months. Under a floating system an exchange-rate price change can absorb pressure; it does not require the same fixed-price intervention.","Резервы после продажи $600 млн, покрытие 600/150=4 месяца вместо 5. Плавающий курс может реагировать изменением цены, а не обязательной защитой паритета.","Sotuvdan keyin zaxira $600 mln, qoplash 600/150=4 oy, avval 5 oy. Suzuvchi kursda bosim almashuv narxi bilan moslashishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-035","d":"hard","sec":180,"k":"B","en":"Country A has nominal GNI per person of $6,000 but a domestic price-level index of 150 relative to a benchmark of 100. Country B has nominal GNI per person of $5,000 and a price-level index of 100. In a simplified price-adjusted comparison, what are their benchmark-price incomes per person and which is higher?","ru":"В стране A номинальный ВНД на человека $6 000 при индексе внутренних цен 150 относительно базы 100. В стране B ВНД $5 000 при индексе цен 100. В упрощённом сравнении с учётом цен чему равны доходы на человека в базовых ценах и в какой стране они выше?","uz":"A mamlakatda jon boshiga nominal YAMD $6000, ichki narx indeksi 150 (baza 100). B mamlakatda nominal YAMD $5000, narx indeksi 100. Narxga tuzatilgan soddalashtirilgan taqqoslashda bazaviy narxlardagi jon boshiga daromad qancha va qaysi biri yuqori?","options_en":["A $6,000; B $5,000, so A higher","A $4,000; B $5,000, so B higher","A $9,000; B $5,000, so A higher","A $4,000; B $3,333, so A higher"],"options_ru":["A $6 000, B $5 000; выше A","A $4 000, B $5 000; выше B","A $9 000, B $5 000; выше A","A $4 000, B $3 333; выше A"],"options_uz":["A $6000, B $5000; A yuqori","A $4000, B $5000; B yuqori","A $9000, B $5000; A yuqori","A $4000, B $3333; A yuqori"],"why":["Price adjustment gives A=$6,000/(150/100)=$4,000 and B=$5,000/(100/100)=$5,000. Higher nominal income need not mean greater real purchasing power.","Корректировка A: $6 000/(150/100)=$4 000; B: $5 000. Более высокий номинальный доход не гарантирует большей покупательной способности.","A tuzatilgan daromadi $6000/(150/100)=$4000, B daromadi $5000. Nominal daromadning kattaligi real xarid quvvatini kafolatlamaydi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-036","d":"hard","sec":195,"k":"A","en":"Before joining a customs union, importers buy 2,000 units from the lowest-cost non-member supplier at a resource cost of $40 per unit plus a $4 import tariff. A union member produces the identical good at a resource cost of $42. After union entry, the common external tariff raises the non-member''s landed price to $48, while member imports enter tariff-free at $42, so trade shifts to the member. What is the effect and extra real resource cost relative to the original supplier?","ru":"До вступления в таможенный союз импортёры покупают 2 000 единиц у поставщика вне союза с ресурсной себестоимостью $40 за единицу плюс пошлина $4. Участник союза производит такой же товар с себестоимостью $42. После вступления общий внешний тариф повышает цену внешнего поставщика до $48, а товар участника поступает без пошлины по $42; закупки переключаются. Каков эффект и дополнительные реальные ресурсные затраты относительно прежнего поставщика?","uz":"Bojxona ittifoqiga kirishdan oldin importchilar 2000 birlikni ittifoqdan tashqari eng arzon ishlab chiqaruvchidan resurs xarajati $40 va boj $4 bilan oladi. Ittifoq a’zosi ayni tovarni $42 resurs xarajatida ishlab chiqaradi. Yangi umumiy tashqi boj tashqi narxni $48 qiladi, a’zo $42 da bojsiz yetkazadi, xarid a’zoga o‘tadi. Bu qanday hodisa va avvalgi manbaga nisbatan qo‘shimcha real resurs xarajati qancha?","options_en":["Trade diversion; $4,000 extra real resource cost","Trade creation; $4,000 resource saving","Trade diversion; $8,000 extra real resource cost","Trade creation; no resource difference"],"options_ru":["Отклонение торговли; дополнительные реальные затраты $4 000","Создание торговли; экономия ресурсов $4 000","Отклонение торговли; дополнительные затраты $8 000","Создание торговли; разницы ресурсов нет"],"options_uz":["Savdoning og‘ishi; qo‘shimcha real xarajat $4000","Savdo yaratilishi; $4000 resurs tejaladi","Savdo og‘ishi; qo‘shimcha xarajat $8000","Savdo yaratilishi; resurs farqi yo‘q"],"why":["The non-member''s underlying resource cost $40 is lower than the member''s $42. Tariff preferences divert imports to a higher-cost producer, adding ($42−$40)×2,000=$4,000 real resource cost. Tax receipts are transfers, not resource costs.","Производственные затраты вне союза $40 ниже союзных $42. Преференция перенаправляет закупки к более дорогому источнику, увеличение реальных затрат ($42−$40)×2 000=$4 000. Пошлина — трансферт.","Ittifoqdan tashqari resurs xarajati $40, a’zoda $42. Boj imtiyozi yuqoriroq xarajatli manbaga yo‘naltiradi: ($42−$40)×2000=$4000 haqiqiy qo‘shimcha xarajat. Boj tushumi transfert."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-039","d":"hard","sec":185,"k":"C","en":"In year one, a country has 420 deaths before age one among 28,000 live births. In year two it records 300 such deaths among 24,000 live births. By how much does the infant mortality rate per 1,000 live births change?","ru":"В первый год в стране зарегистрировано 420 смертей детей до одного года при 28 000 живорождений. Во второй год — 300 смертей при 24 000 живорождений. Как изменяется коэффициент младенческой смертности на 1 000 живорождений?","uz":"Birinchi yilda mamlakatda 28 000 tirik tug‘ilishdan bir yoshgacha 420 o‘lim, ikkinchi yilda 24 000 tug‘ilishdan 300 o‘lim qayd etildi. Har 1000 tirik tug‘ilishga chaqaloq o‘lim koeffitsienti qanchaga o‘zgaradi?","options_en":["Increases from 12.5 to 15.0, by 2.5","Falls from 15.0 to 10.7, by 4.3","Falls from 15.0 to 12.5, by 2.5","Falls from 1.5 to 1.25, by 0.25"],"options_ru":["Растёт с 12,5 до 15,0, на 2,5","Падает с 15,0 до 10,7, на 4,3","Падает с 15,0 до 12,5, на 2,5","Падает с 1,5 до 1,25, на 0,25"],"options_uz":["12,5 dan 15,0 ga, 2,5 oshadi","15,0 dan 10,7 ga, 4,3 tushadi","15,0 dan 12,5 ga, 2,5 tushadi","1,5 dan 1,25 ga, 0,25 tushadi"],"why":["Rates are 420/28,000×1,000=15.0 and 300/24,000×1,000=12.5. The infant mortality rate falls by 2.5 deaths per 1,000 live births.","Коэффициенты 420/28 000×1 000=15,0 и 300/24 000×1 000=12,5. Снижение составляет 2,5 случая на 1 000 живорождений.","Koeffitsientlar 420/28 000×1000=15,0 va 300/24 000×1000=12,5. Har 1000 tug‘ilishga 2,5 ta kamayish."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-041","d":"hard","sec":180,"k":"D","en":"Domestic machinery exporters need two tonnes of imported steel for each machine. A 20% tariff raises imported steel''s price from $400 to $480 per tonne and is fully passed through to input buyers. If 100 machines are made with all other prices unchanged, what is the additional steel-input cost, and which policy trade-off does it reveal?","ru":"Отечественные экспортёры оборудования используют по две тонны импортной стали на машину. Пошлина 20% повышает цену импортной стали с $400 до $480 за тонну и полностью переносится на покупателей ресурсов. При выпуске 100 машин и неизменных прочих ценах каковы дополнительные затраты на сталь и какой компромисс это выявляет?","uz":"Mahalliy uskuna eksportchilari har mashina uchun ikki tonna import po‘lat ishlatadi. 20% boj po‘lat narxini $400 dan $480 ga oshiradi va xaridorga to‘liq o‘tadi. Boshqa narxlar o‘zgarmasdan 100 mashina tayyorlansa, po‘lat uchun qo‘shimcha xarajat qancha va qanday siyosiy muvozanat ko‘rinadi?","options_en":["$8,000; steel protection necessarily increases machine exports","$16,000; the tariff has no effect on exporters","$80,000; machines automatically become cheaper abroad","$16,000; upstream producer protection can damage downstream export competitiveness"],"options_ru":["$8 000; защита стали обязательно повышает экспорт машин","$16 000; пошлина не влияет на экспортёров","$80 000; машины автоматически дешевеют за границей","$16 000; защита поставщиков ресурсов может снизить конкурентоспособность экспортёров"],"options_uz":["$8000; po‘lat himoyasi uskuna eksportini albatta oshiradi","$16 000; boj eksportchiga ta’sir qilmaydi","$80 000; mashina chetda avtomatik arzonlashadi","$16 000; yuqori bosqichdagi himoya keyingi mahsulot eksportiga zarar berishi mumkin"],"why":["Each machine uses 2 tonnes, so 100 use 200 tonnes. The tariff adds $80 per tonne, increasing costs by 200×$80=$16,000. Protecting steel firms can harm downstream exporters.","100 ta mashina 200 tonna po‘lat ishlatadi. Har tonnaga $80 qo‘shimcha, jami $16 000. Po‘lat ishlab chiqaruvchilarni himoyalash keyingi eksportchilar xarajatini oshiradi.","100 машин требуют 200 тонн стали. Удорожание $80 за тонну повышает затраты на $16 000. Защита сталелитейщиков способна ухудшить конкурентоспособность машиностроения."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-043","d":"hard","sec":180,"k":"A","en":"A resource-dependent country has an export-price index of 100 and an import-price index of 100 in the base period. Cocoa export prices later fall to an index of 80 while machinery import prices rise to 120. What is its new terms-of-trade index and approximate percentage deterioration?","ru":"В стране, зависящей от сырьевого экспорта, индексы экспортных и импортных цен базового периода равны 100. Позднее индекс экспортных цен какао падает до 80, индекс цен импортируемого оборудования растёт до 120. Каков новый индекс условий торговли и примерный процент ухудшения?","uz":"Xomashyo eksportiga bog‘liq mamlakatda bazaviy eksport va import narx indekslari 100. Keyin kakao eksport narx indeksi 80 ga tushadi, import uskuna narxi indeksi 120 ga oshadi. Yangi savdo shartlari indeksi va taxminiy yomonlashish foizi qancha?","options_en":["66.7; deterioration about 33.3%","150; improvement about 50%","80; deterioration about 20%","120; improvement about 20%"],"options_ru":["66,7; ухудшение примерно на 33,3%","150; улучшение примерно на 50%","80; ухудшение примерно на 20%","120; улучшение примерно на 20%"],"options_uz":["66,7; taxminan 33,3% yomonlashish","150; taxminan 50% yaxshilanish","80; taxminan 20% yomonlashish","120; taxminan 20% yaxshilanish"],"why":["Terms of trade=export-price index/import-price index×100=80/120×100≈66.7 versus 100 initially. That is a fall of about 33.3% and reduces purchasing power of exports over imports.","Условия торговли =80/120×100≈66,7 вместо 100. Снижение около 33,3% уменьшает количество импорта, приобретаемого на экспортную выручку при прочих равных.","Savdo shartlari 80/120×100≈66,7, avval 100 edi. Taxminan 33,3% yomonlashish eksportning import xarid quvvatini pasaytiradi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-045","d":"hard","sec":180,"k":"B","en":"After currency depreciation, estimated long-run price elasticities of demand for exports and imports are respectively 0.6 and 0.7 in absolute value. Quantities initially respond slowly because contracts are fixed. What do the Marshall–Lerner condition and adjustment delay jointly suggest?","ru":"После обесценения валюты долгосрочные ценовые эластичности спроса на экспорт и импорт по модулю оцениваются как 0,6 и 0,7. Сначала объёмы медленно меняются из-за фиксированных контрактов. Что совместно предполагают условие Маршалла–Лернера и задержка адаптации?","uz":"Valuta qadrsizlangach eksport va import talabining uzoq muddatli narx elastikliklari mutlaq 0,6 va 0,7. Dastlab hajmlar qat’iy shartnomalar sabab sekin moslashadi. Marshall–Lerner sharti va moslashish kechikishi birga nimani ko‘rsatadi?","options_en":["Elasticities sum to 0.1, so the balance must worsen forever","Elasticities sum to 1.3; long-run improvement is possible after an initial worsening (J-curve), other things equal","Elasticities sum to 1.3, so improvement must be immediate","Elasticities do not matter when the nominal exchange rate changes"],"options_ru":["Сумма эластичностей 0,1; сальдо обязано ухудшаться всегда","Сумма 1,3; со временем улучшение возможно после первоначального ухудшения (J-кривая), при прочих равных","Сумма 1,3; улучшение обязано быть немедленным","Эластичности не имеют значения при изменении курса"],"options_uz":["Elastikliklar yig‘indisi 0,1; balans doim yomonlashishi shart","Yig‘indi 1,3; dastlab J-egri bo‘yicha yomonlashib, keyin yaxshilanishi mumkin, boshqa shartlar teng","Yig‘indi 1,3; darhol yaxshilanish shart","Nominal kurs o‘zgarganda elastiklik ahamiyatsiz"],"why":["Absolute elasticities sum to 0.6+0.7=1.3>1, satisfying the Marshall–Lerner condition for a potential eventual trade-balance improvement. Slow quantity adjustment can create initial J-curve deterioration.","Сумма модулей 0,6+0,7=1,3>1 выполняет условие Маршалла–Лернера для возможного последующего улучшения. Запаздывающая реакция объёмов допускает начальное ухудшение.","Mutlaq elastikliklar yig‘indisi 0,6+0,7=1,3>1. Marshall–Lerner sharti keyingi yaxshilanishga mos, hajm sekin moslashsa avval J-egri yomonlashishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-063","d":"hard","sec":190,"k":"C","en":"A country starts with a current-account surplus of $20m. A rate cut raises domestic income and induces $10m extra imports, but an exchange-rate depreciation independently raises exports by $12m and reduces imports by another $5m. With no other changes or overlap, what is the new current-account balance?","ru":"Первоначальный профицит текущего счёта $20 млн. Снижение ставки повышает внутренний доход и вызывает дополнительные импортные закупки на $10 млн. Но связанное с курсом обесценение независимо увеличивает экспорт на $12 млн и уменьшает импорт ещё на $5 млн. Прочих эффектов и пересечений нет. Каково новое сальдо?","uz":"Mamlakat joriy hisobida dastlab $20 mln profitsit bor. Stavka pasayishi daromadni oshirib, qo‘shimcha $10 mln import yaratadi. Valuta qadrsizlanishi mustaqil ravishda eksportni $12 mln oshirib, importni yana $5 mln kamaytiradi. Boshqa ta’sir va takror yo‘q. Yangi balans qancha?","options_en":["+$3m; the surplus disappears","+$13m; interest cuts always remove surpluses","+$27m; exchange-rate effects more than offset higher income-induced imports","−$7m; depreciation necessarily causes a deficit"],"options_ru":["+$3 млн; профицит исчезает","+$13 млн; снижение ставки всегда устраняет профицит","+$27 млн; валютный эффект более чем компенсирует импорт из-за роста дохода","−$7 млн; обесценение обязательно создаёт дефицит"],"options_uz":["+$3 mln; profitsit yo‘qoladi","+$13 mln; stavka pasayishi doim profitsitni yo‘q qiladi","+$27 mln; kurs ta’siri daromad sabab qo‘shimcha importni ortig‘i bilan qoplaydi","−$7 mln; qadrsizlanish albatta taqchillik yaratadi"],"why":["Net change to the current account is −$10m+$12m+$5m=+$7m. The surplus rises from $20m to $27m rather than falling as policymakers intended.","Текущий счёт меняется на −$10+$12+$5=+$7 млн. Профицит растёт с $20 до $27 млн вопреки исходной цели.","Joriy hisob o‘zgarishi −$10+$12+$5=+$7 mln. Profitsit maqsadga zid ravishda $20 mln dan $27 mln ga oshadi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-065","d":"hard","sec":185,"k":"D","en":"A government owes $100m in foreign-currency debt with an annual interest rate of 5%. The exchange rate depreciates from 10,000 to 12,000 local units per foreign unit. Annual export receipts fall from $9m to $7m in foreign currency. What are the new annual interest bill in local currency and the interest bill as a share of export receipts?","ru":"Государство должно $100 млн валютного долга под 5% годовых. Курс национальной валюты ослабевает с 10 000 до 12 000 местных единиц за иностранную. Годовая экспортная выручка падает с $9 млн до $7 млн. Какова новая годовая сумма процентов в местной валюте и доля процентных выплат в экспортной выручке?","uz":"Davlat $100 mln xorijiy valuta qarziga yiliga 5% foiz to‘laydi. Kurs bir xorijiy birlik uchun 10 000 dan 12 000 mahalliy birlikka qadrsizlanadi. Yillik eksport tushumi $9 mln dan $7 mln ga tushadi. Yangi yillik foiz to‘lovi mahalliy valutada qancha va eksport tushumiga nisbati qanday?","options_en":["50bn local units; about 55.6%","60bn local units; exactly 5%","12bn local units; about 71.4%","60bn local units; about 71.4%"],"options_ru":["50 млрд местных единиц; около 55,6%","60 млрд местных единиц; ровно 5%","12 млрд местных единиц; около 71,4%","60 млрд местных единиц; около 71,4%"],"options_uz":["50 mlrd mahalliy birlik; taxminan 55,6%","60 mlrd mahalliy birlik; aynan 5%","12 mlrd mahalliy birlik; taxminan 71,4%","60 mlrd mahalliy birlik; taxminan 71,4%"],"why":["Foreign-currency annual interest is 5%×$100m=$5m. In local units it is $5m×12,000=60bn. Relative to $7m export receipts, interest is 5/7≈71.4%, indicating heightened external debt-service stress.","Валютные проценты 5%×$100 млн=$5 млн, в местной валюте $5 млн×12 000=60 млрд единиц. К экспортной выручке доля 5/7≈71,4%.","Yillik xorijiy foiz $100 mln×5%=$5 mln. Mahalliy to‘lov $5 mln×12 000=60 mlrd birlik, eksport tushumiga nisbati 5/7≈71,4%."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-009","d":"medium","sec":155,"k":"B","en":"A country''s population at the start of a year is 2 million. During the year there are 40,000 births, 25,000 deaths, 15,000 immigrants and 25,000 emigrants. Assuming no other changes, what are its natural increase, net migration and overall population growth rate?","ru":"На начало года население страны 2 млн. За год было 40 000 рождений, 25 000 смертей, 15 000 иммигрантов и 25 000 эмигрантов. Без прочих изменений найдите естественный прирост, миграционное сальдо и общий темп прироста населения.","uz":"Yil boshida mamlakat aholisi 2 mln. Yil davomida 40 000 tug‘ilish, 25 000 o‘lim, 15 000 immigratsiya va 25 000 emigratsiya bo‘ldi. Boshqa ta’sirsiz tabiiy o‘sish, sof migratsiya va umumiy aholi o‘sish sur’ati qancha?","options_en":["+15,000; +10,000; 1.25%","+15,000; −10,000; 0.25%","−15,000; +10,000; −0.25%","+40,000; −25,000; 0.75%"],"options_ru":["+15 000; +10 000; 1,25%","+15 000; −10 000; 0,25%","−15 000; +10 000; −0,25%","+40 000; −25 000; 0,75%"],"options_uz":["+15 000; +10 000; 1,25%","+15 000; −10 000; 0,25%","−15 000; +10 000; −0,25%","+40 000; −25 000; 0,75%"],"why":["Natural increase is 40,000−25,000=15,000; net migration 15,000−25,000=−10,000. Total increase 5,000/2,000,000=0.25%.","Естественный прирост 40 000−25 000=15 000, миграционное сальдо 15 000−25 000=−10 000. Общий прирост 5 000/2 000 000=0,25%.","Tabiiy o‘sish 40 000−25 000=15 000, migratsiya 15 000−25 000=−10 000. Jami o‘sish 5 000/2 000 000=0,25%."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-010","d":"medium","sec":145,"k":"D","en":"Country A has 9,000 births among 600,000 people; country B has 10,800 births among 675,000 people in the same year. Which comparison of crude birth rates per 1,000 population is correct?","ru":"В стране A за год зарегистрировано 9 000 рождений при населении 600 000, в стране B — 10 800 при населении 675 000. Как верно сопоставить общие коэффициенты рождаемости на 1 000 жителей?","uz":"A mamlakatda yil davomida 600 000 aholiga 9000 tug‘ilish, B mamlakatda 675 000 aholiga 10 800 tug‘ilish to‘g‘ri keladi. Har 1000 kishiga umumiy tug‘ilish koeffitsientlarini qaysi javob to‘g‘ri taqqoslaydi?","options_en":["A 15; B 14, so A is higher","A 9; B 10.8, so B is higher","A 16; B 15, so A is higher","A 15; B 16, so B is higher by one per 1,000"],"options_ru":["A — 15; B — 14, выше A","A — 9; B — 10,8, выше B","A — 16; B — 15, выше A","A — 15; B — 16, B выше на единицу на 1 000"],"options_uz":["A — 15; B — 14, A yuqori","A — 9; B — 10,8, B yuqori","A — 16; B — 15, A yuqori","A — 15; B — 16, B har 1000 da birga yuqori"],"why":["A has 9,000/600,000×1,000=15 births per 1,000; B has 10,800/675,000×1,000=16. The larger birth count alone does not establish the rate.","A: 9 000/600 000×1 000=15, B: 10 800/675 000×1 000=16. Само абсолютное число рождений не заменяет коэффициент.","A: 9000/600 000×1000=15, B: 10 800/675 000×1000=16. Faqat tug‘ilish soni koeffitsientni bildirmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-021","d":"medium","sec":155,"k":"C","en":"A region has 400,000 residents, of whom 100,000 live in urban areas. New export factories attract 20,000 rural residents to cities, without changing the region''s total population. What is the new urban share and the increase in percentage points?","ru":"В регионе проживает 400 000 человек, из них 100 000 — в городах. Новые экспортные заводы привлекают 20 000 сельских жителей в города, общая численность населения региона не меняется. Какова новая доля городского населения и её увеличение в процентных пунктах?","uz":"Hududda 400 000 kishi yashaydi, ulardan 100 000 shaharda. Yangi eksport zavodlari 20 000 qishloq aholisini shaharga jalb qiladi, umumiy aholi o‘zgarmaydi. Yangi shahar ulushi va foiz punktdagi o‘sish qancha?","options_en":["25%; increase 5 points","30%; increase 20 points","30%; increase 5 points","35%; increase 10 points"],"options_ru":["25%; рост на 5 п.п.","30%; рост на 20 п.п.","30%; рост на 5 п.п.","35%; рост на 10 п.п."],"options_uz":["25%; 5 foiz punkt oshadi","30%; 20 foiz punkt oshadi","30%; 5 foiz punkt oshadi","35%; 10 foiz punkt oshadi"],"why":["Initial urban share is 100,000/400,000=25%. New urban population 120,000/400,000=30%, five percentage points higher. This is internal rural-to-urban migration.","Исходная доля 100 000/400 000=25%. После миграции 120 000/400 000=30%, рост на пять процентных пунктов.","Dastlab shahar ulushi 100 000/400 000=25%. Keyin 120 000/400 000=30%, besh foiz punkt oshadi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-024","d":"medium","sec":150,"k":"B","en":"Two countries have similar PPP-adjusted income per person. Country X has more years of schooling on average but lower life expectancy than Country Y. Which conclusion about their overall Human Development Index follows without the precise normalised component scores?","ru":"Две страны имеют сходный доход на человека с учётом ППС. В стране X средняя продолжительность обучения выше, но ожидаемая продолжительность жизни ниже, чем в Y. Какой вывод об их общем индексе человеческого развития возможен без точных нормализованных значений компонентов?","uz":"Ikki mamlakatning PPP bo‘yicha jon boshiga daromadi o‘xshash. X mamlakatda o‘qish yillari ko‘proq, ammo umr davomiyligi Y dan past. Aniq normallashtirilgan komponent ballarisiz umumiy Inson Taraqqiyoti Indeksi haqida qanday xulosa chiqarish mumkin?","options_en":["X must have the higher HDI because education always dominates","The overall HDI ranking is not determined; health and education differences must be combined with the income component","Y must have the higher HDI because health alone determines it","Equal PPP income forces identical HDI scores"],"options_ru":["У X индекс обязательно выше, поскольку образование всегда доминирует","Общий рейтинг не определён: показатели здоровья и образования нужно объединить с доходным компонентом","У Y индекс обязательно выше, поскольку его определяет только здоровье","Равенство доходов по ППС гарантирует одинаковый ИЧР"],"options_uz":["X HDI albatta yuqori, chunki ta’lim doim ustun","Umumiy HDI tartibi noma’lum; sog‘liq va ta’lim ko‘rsatkichlarini daromad bilan birlashtirish kerak","Y HDI albatta yuqori, chunki uni faqat sog‘liq belgilaydi","PPP daromadi teng bo‘lsa HDI ham ayni bo‘ladi"],"why":["HDI combines education, health and income dimensions. Better education but poorer health creates offsetting effects, so relative HDI cannot be inferred without the component values and weighting method.","ИЧР объединяет образование, здоровье и доход. Улучшение одного измерения при ухудшении другого не позволяет определить общий рейтинг без значений компонентов.","HDI ta’lim, sog‘liq va daromadni birlashtiradi. Ta’lim yaxshiroq, sog‘liq yomonroq bo‘lsa komponentlar qiymatisiz umumiy reyting aniqlanmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-040","d":"medium","sec":160,"k":"A","en":"In Country A, the nominal monthly wage is $1,000 and a standard food basket costs $250. In Country B, the nominal monthly wage is $900 and the identical basket costs $180. Ignoring other goods, how many such baskets can each wage buy, and which country has greater purchasing power measured in this basket?","ru":"В стране A номинальная зарплата $1 000 в месяц, стандартная продуктовая корзина стоит $250. В стране B зарплата $900, идентичная корзина — $180. Игнорируя прочие товары, сколько таких корзин можно купить и где покупательная способность относительно данной корзины выше?","uz":"A mamlakatda nominal oylik $1000, standart oziq-ovqat savati $250. B mamlakatda oylik $900, ayni savat $180. Boshqa tovarlarni hisoblamasdan har oylikka necha savat olish mumkin va shu savat bo‘yicha xarid quvvati qayerda yuqori?","options_en":["A 4 baskets; B 5 baskets, so B has greater basket-specific purchasing power","A 5 baskets; B 4, so A has greater purchasing power","Both 4 baskets because wages are broadly similar","A 4 baskets; B 5, proving B has higher welfare in every dimension"],"options_ru":["A — 4 корзины, B — 5; по данной корзине покупательная способность выше в B","A — 5, B — 4; выше в A","В обеих странах по 4 корзины из-за сходства зарплат","A — 4, B — 5; это доказывает превосходство B по всем аспектам благосостояния"],"options_uz":["A 4 savat, B 5 savat; ayni savat bo‘yicha B xarid quvvati yuqori","A 5, B 4; A yuqori","Ikkalasida 4 savat, chunki ish haqi yaqin","A 4, B 5; bu B har tomonlama farovonligi yuqoriligini isbotlaydi"],"why":["A can buy $1,000/$250=4 baskets; B can buy $900/$180=5. This supports only a basket-specific purchasing-power comparison, not an overall welfare ranking.","В A можно купить $1 000/$250=4 корзины, в B $900/$180=5. Вывод относится к данной корзине, а не ко всем аспектам благосостояния.","A $1000/$250=4 savat, B $900/$180=5 savat oladi. Bu faqat shu savat bo‘yicha xarid quvvatini taqqoslaydi, umumiy farovonlikni emas."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-047","d":"medium","sec":160,"k":"D","en":"A factory can buy a crucial part domestically for $60 or import it for $50. Imports face an independently estimated expected disruption cost of $8 per part, while domestic sourcing has negligible disruption cost. Assuming risks can be valued in money and there are no other differences, which sourcing choice minimises expected total cost, and what does it illustrate?","ru":"Завод может покупать ключевую деталь внутри страны за $60 или импортировать за $50. Для импорта независимая оценка ожидаемых потерь от сбоев составляет $8 на деталь, для местных поставок потери пренебрежимо малы. Если риски допустимо оценивать в деньгах и прочих отличий нет, какой выбор минимизирует ожидаемые затраты и что это иллюстрирует?","uz":"Zavod muhim detalni mahalliy ishlab chiqaruvchidan $60 ga yoki import qilib $50 ga olishi mumkin. Import uzilishining pulda baholangan kutilgan zarari har detalga $8, mahalliy ta’minotda deyarli nol. Boshqa farqlar bo‘lmasa qaysi xarid kutilgan jami xarajatni minimallashtiradi va nimani ko‘rsatadi?","options_en":["Domestic, because imported input costs $68 after the risk adjustment","Domestic, because foreign trade always has higher costs","Both are equally costly at $60","Import at $58 expected cost; global sourcing can remain cheaper even after accounting for disruption risk"],"options_ru":["Внутри страны, поскольку импорт с риском обходится в $68","Внутри страны, поскольку внешняя торговля всегда дороже","Оба варианта стоят $60","Импорт с ожидаемыми затратами $58; глобальные закупки могут быть выгодны даже с риском сбоев"],"options_uz":["Mahalliy, chunki import xavf bilan $68 turadi","Mahalliy, chunki tashqi savdo doim qimmat","Ikkalasi $60 turadi","Importning kutilgan xarajati $58; uzilish xavfini hisobga olganda ham global ta’minot arzon bo‘lishi mumkin"],"why":["Imported expected cost is $50+$8=$58, below the $60 domestic alternative. This illustrates a cost advantage tempered by supply-chain risk, not proof that imports are always better.","Ожидаемые затраты импорта $50+$8=$58 ниже местных $60. Преимущество международного снабжения сохраняется в данном случае, но сопровождается риском сбоев.","Import kutilgan xarajati $50+$8=$58, mahalliy $60 dan past. Global ta’minot bu misolda arzon, lekin uzilish xavfi mavjud."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-061","d":"medium","sec":150,"k":"C","en":"A foreign company invests $100m to build a new factory. Of this, $40m purchases imported machinery and $60m pays for domestic construction and installation. Another investor instead spends $100m buying shares from an existing domestic factory owner. Which comparison of immediate host-economy effects is best supported?","ru":"Иностранная компания вкладывает $100 млн в строительство нового завода: $40 млн идут на импортное оборудование, $60 млн — на местные строительные и монтажные работы. Другой инвестор тратит $100 млн на покупку акций у прежнего владельца действующего завода. Какое сравнение немедленных эффектов для принимающей экономики наиболее обоснованно?","uz":"Xorijiy kompaniya $100 mln ga yangi zavod quradi: $40 mln import uskuna, $60 mln mahalliy qurilish va montajga ketadi. Boshqa investor $100 mln ga mavjud zavod egasidan aksiyalar sotib oladi. Qabul qiluvchi iqtisodiyot uchun darhol ta’sirlar qanday farqlanadi?","options_en":["Both transactions necessarily add identical new factories","The share purchase directly creates $100m of new physical capital","The new factory creates additional productive assets and domestic construction demand, while buying existing shares mainly changes ownership","Neither can be classed as direct investment under any circumstances"],"options_ru":["Оба вложения обязательно создают одинаковые новые заводы","Покупка акций непосредственно создаёт $100 млн нового физического капитала","Строительство создаёт новые производственные активы и спрос на местные работы, покупка существующих акций преимущественно меняет владельца","Ни один вариант не может относиться к ПИИ"],"options_uz":["Ikkala bitim bir xil yangi zavod yaratadi","Aksiya xaridi bevosita $100 mln yangi jismoniy kapital yaratadi","Yangi zavod qo‘shimcha ishlab chiqarish aktivlari va mahalliy qurilish talabi yaratadi, mavjud aksiyani olish asosan egalikni o‘zgartiradi","Ikkala bitim ham PII bo‘la olmaydi"],"why":["Greenfield investment builds new capacity and purchases domestic construction services, whereas buying existing shares transfers ownership and does not by itself create a new plant. Control criteria determine FDI classification.","Строительство нового завода расширяет физические мощности и спрос на местные работы. Покупка существующих акций меняет собственность и сама по себе не строит завод; ПИИ зависит от участия и контроля.","Yangi zavod yangi quvvat va mahalliy qurilish talabi yaratadi; mavjud aksiyani olish egalikni o‘zgartiradi, avtomatik yangi zavod qurmaydi. PII tasnifi nazoratga bog‘liq."]},{"ref":"EC9708:G2:EC9708-G2-T7-P-062","d":"medium","sec":145,"k":"B","en":"A country''s real GDP rises by 6% while its population grows by 8% over the same period. Using exact index ratios, what is the approximate change in real GDP per person?","ru":"Реальный ВВП страны вырос на 6%, а население за тот же период — на 8%. Используя точное отношение индексов, найдите приблизительное изменение реального ВВП на человека.","uz":"Mamlakat real YaIMi 6%, aholisi esa shu davrda 8% oshdi. Indekslarning aniq nisbatidan foydalanib jon boshiga real YaIMning taxminiy o‘zgarishini toping.","options_en":["+2.0%","−1.85%","+14.0%","−2.0% exactly"],"options_ru":["+2,0%","−1,85%","+14,0%","Ровно −2,0%"],"options_uz":["+2,0%","−1,85%","+14,0%","Aynan −2,0%"],"why":["Real GDP per person changes by the factor 1.06/1.08≈0.98148, a fall of about 1.85%, not exactly the two-percentage-point approximation.","Коэффициент 1,06/1,08≈0,98148 означает снижение реального ВВП на человека примерно на 1,85%, а не ровно на два процентных пункта.","Jon boshiga real YaIM koeffitsienti 1,06/1,08≈0,98148, taxminan 1,85% kamayish. Ikki foiz punktni ayirish faqat yaqinlashish."]}]'::jsonb;
 x jsonb; o record; new_id bigint; i int; ix int; k text; b text; cnt int; e int; m int; h int; why_ru text; why_uz text; why_en text;
BEGIN
 IF jsonb_array_length(d)<>28 THEN RAISE EXCEPTION 'expected_28'; END IF;
 SELECT count(*) INTO cnt FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id WHERE p.subject_id=7 AND p.tour_no=7 AND l.is_active;
 IF cnt<>70 THEN RAISE EXCEPTION 'pool_precondition: %',cnt; END IF;
 -- Historical T7 question 048 has an active editorial V2 and prior answered V1; never deactivate or overwrite either.
 IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
   JOIN public.questions q ON q.id=l.question_id WHERE p.subject_id=7 AND p.tour_no=7
   AND l.is_active AND q.book_ref='EC9708:G2:EC9708-G2-T7-P-048-V2')<>1
 THEN RAISE EXCEPTION 'T7_P048_historical_active_version_changed'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(d) LOOP
   b:=x->>'ref';k:=x->>'k';ix:=ascii(k)-65;
   IF k NOT IN ('A','B','C','D') OR x->>'d' NOT IN ('medium','hard') OR jsonb_array_length(x->'options_en')<>4 OR jsonb_array_length(x->'options_ru')<>4 OR jsonb_array_length(x->'options_uz')<>4 THEN RAISE EXCEPTION 'invalid_question: %',b; END IF;
   SELECT q.*, l.pool_id,l.order_no INTO STRICT o FROM public.questions q
      JOIN public.practice_pool_questions l ON l.question_id=q.id AND l.is_active
      JOIN public.practice_pools p ON p.id=l.pool_id AND p.tour_no=7
      WHERE q.subject_id=7 AND p.subject_id=7 AND q.book_ref=b;
   IF EXISTS(SELECT 1 FROM public.practice_answers a WHERE a.question_id=o.id) OR EXISTS(SELECT 1 FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=b||'-V2') THEN RAISE EXCEPTION 'history_or_version_conflict: %',b; END IF;
   why_ru:=x->'why'->>1;why_uz:=x->'why'->>2;why_en:=x->'why'->>0;
   INSERT INTO public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
   VALUES(o.subject_id,o.topic,o.subtopic,x->>'d','mcq',x->>'en',(x->'options_en')::text,k,
       'Correct: '||(x->'options_en'->>ix)||E'\n'||why_en,NULL,true,
       x->>'ru',x->>'uz',x->>'en',(x->'options_ru')::text,(x->'options_uz')::text,(x->'options_en')::text,
       'Ответ: '||(x->'options_ru'->>ix)||E'\n'||why_ru,
       'Javob: '||(x->'options_uz'->>ix)||E'\n'||why_uz,
       'Correct: '||(x->'options_en'->>ix)||E'\n'||why_en,b||'-V2',(x->>'sec')::int,o.quality_flag,'published')
   RETURNING id INTO new_id;
   UPDATE public.practice_pool_questions SET is_active=false WHERE pool_id=o.pool_id AND question_id=o.id AND is_active;
   GET DIAGNOSTICS cnt=ROW_COUNT;
   IF cnt<>1 THEN RAISE EXCEPTION 'link_count: %',b; END IF;
   INSERT INTO public.practice_pool_questions(pool_id,question_id,order_no,is_active) VALUES(o.pool_id,new_id,o.order_no,true);
   INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason) VALUES(o.id,new_id,'replacement','Economics T7 difficulty content replacement; historical question retained');
   FOR i IN 0..3 LOOP
     INSERT INTO public.question_answer_diagnostics(question_id,answer_kind,answer_key,answer_value,is_correct,mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,rule_json,quality_status)
     VALUES(new_id,'mcq_option',chr(65+i),NULL,i=ix,CASE WHEN i=ix THEN NULL ELSE 'multi_step_economic_reasoning' END,o.subtopic,
       'Выбрано: '||(x->'options_ru'->>i)||E'\n'||why_ru||E'\nОтвет: '||(x->'options_ru'->>ix),
       'Tanlov: '||(x->'options_uz'->>i)||E'\n'||why_uz||E'\nJavob: '||(x->'options_uz'->>ix),
       'Selected: '||(x->'options_en'->>i)||E'\n'||why_en||E'\nCorrect: '||(x->'options_en'->>ix),
       CASE WHEN i=ix THEN NULL ELSE 'Проверьте способ решения.' END,CASE WHEN i=ix THEN NULL ELSE 'Yechimni qayta tekshiring.' END,CASE WHEN i=ix THEN NULL ELSE 'Review the method.' END,
       jsonb_build_object('diagnostic_code','EC9708_G2_T7P'||substring(b from 'P-([0-9]{3})')||'_V2_'||chr(65+i)),'published');
   END LOOP;
 END LOOP;
 UPDATE public.questions q SET difficulty=CASE WHEN right(q.book_ref,3) IN ('003','011','015','016','026','029','034','044','046','048','050','051','054','055','056','057','058','064','066','067','068','069') THEN 'medium' ELSE 'easy' END
 WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T7-P-[0-9]{3}$'
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d) z WHERE z->>'ref'=q.book_ref);
 GET DIAGNOSTICS cnt=ROW_COUNT;
 IF cnt<>42 THEN RAISE EXCEPTION 'unchanged_count: %',cnt; END IF;
 SELECT count(*),count(*) FILTER(WHERE q.difficulty='easy'),count(*) FILTER(WHERE q.difficulty='medium'),count(*) FILTER(WHERE q.difficulty='hard')
 INTO cnt,e,m,h FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id JOIN public.questions q ON q.id=l.question_id
 WHERE p.subject_id=7 AND p.tour_no=7 AND l.is_active;
 IF cnt<>70 OR e<>20 OR m<>30 OR h<>20 THEN RAISE EXCEPTION 'postcondition_fail: %,%,%,%',cnt,e,m,h; END IF;
END $t$;
COMMIT;
